// Public brand: Stone & Sprig.
import {writeFile,mkdir} from 'node:fs/promises';
import {fileURLToPath} from 'node:url';
import {dirname,resolve} from 'node:path';
import {shop,products,collections,guides} from '../catalogue.mjs';
import {money,escapeHtml as e} from '../garden-core.mjs';
import {productGrid} from '../render.mjs';
import {productArt,sprig,botanical} from '../art.mjs';
const project=resolve(dirname(fileURLToPath(import.meta.url)),'..');
const pages=new Map();
const searchConnections=JSON.parse(await (await import('node:fs/promises')).readFile(resolve(project,'search-connections.json'),'utf8'));
const verificationMeta=()=>[['google-site-verification','googleVerification'],['msvalidate.01','bingVerification'],['yandex-verification','yandexVerification']].filter(([,key])=>/^[a-zA-Z0-9_-]{8,200}$/.test(searchConnections[key]||'')).map(([name,key])=>`<meta name="${name}" content="${e(searchConnections[key])}">`).join('');
const basketIcon='<svg viewBox="0 0 24 24" fill="none" aria-hidden="true"><path d="M3 9H21L19 21H5L3 9ZM7 9L12 2L17 9M9 12V18M15 12V18" stroke="currentColor" stroke-width="1.5" stroke-linecap="round" stroke-linejoin="round"/></svg>';
const nav=[['shop.html','Shop','shop'],['garden-projects.html','Garden projects','projects'],['garden-planner.html','Garden planner','planner'],['journal.html','Journal','journal'],['community.html','The Potting Bench','community']];
const coming='<strong>The shop is coming soon.</strong> Browse the planned range and save ideas. Stock has not been confirmed and online payment is closed.';
const button=(u,path,label,style='')=>`<a class="button ${style}" href="${u(path)}">${label}</a>`;
const sectionHead=(label,title,text='',link='')=>`<div class="section-heading"><div><span class="eyebrow">${label}</span><h2>${title}</h2></div>${text?`<p>${text}</p>`:link}</div>`;
function header(u,active){return `<div class="launch-bar"><div class="wrap"><span>Garden projects, practical ideas &amp; a shop taking root</span><a href="${u('delivery.html')}">Shop coming soon · payment closed</a></div></div><header class="site-header"><div class="wrap header-row"><a class="brand" href="${u('index.html')}" aria-label="Stone & Sprig home"><img class="stone-brand-logo" src="${u('assets/stone-sprig-logo.png')}" width="210" height="140" alt="Stone &amp; Sprig — Garden Design &amp; Outdoor Projects"></a><nav class="main-nav" id="main-nav" aria-label="Main navigation">${nav.map(([path,label,key])=>`<a href="${u(path)}" ${active===key?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="header-actions"><a href="https://stone-and-sprig.taccountant.chatgpt.site/portal">My account</a><button type="button" class="menu-button" data-menu aria-controls="main-nav" aria-expanded="false">Menu</button><button type="button" class="basket-button" data-open-basket aria-haspopup="dialog" aria-controls="basket-dialog">${basketIcon}Basket <span class="basket-count" data-basket-count aria-label="0 saved items">0</span></button></div></div></header>`;}
function footer(u){return `<footer class="site-footer"><div class="wrap"><div class="footer-grid"><div><a class="brand" href="${u('index.html')}"><img class="stone-brand-logo" src="${u('assets/stone-sprig-logo.png')}" width="210" height="140" alt="Stone &amp; Sprig — Garden Design &amp; Outdoor Projects"></a><p>For everyday gardens, small beginnings and a little more time outside. Practical ideas, a planned essentials shop and garden projects discussed individually.</p></div><div><h3>Explore</h3><a href="https://stone-and-sprig.taccountant.chatgpt.site/portal">Customer area</a><a href="https://stone-and-sprig.taccountant.chatgpt.site/manage">Owner dashboard</a>${[['shop.html','Planned shop'],['collections.html','Garden collections'],['garden-projects.html','Discuss a project'],['garden-planner.html','Make a garden plan']].map(([p,t])=>`<a href="${u(p)}">${t}</a>`).join('')}</div><div><h3>Gather &amp; learn</h3>${[['journal.html','The garden journal'],['community.html','The Potting Bench'],['about.html','Our approach'],['contact.html','Contact Leighton']].map(([p,t])=>`<a href="${u(p)}">${t}</a>`).join('')}</div><div><h3>A little help</h3>${[['help.html','Questions & answers'],['delivery.html','Shop & delivery status'],['returns.html','Orders & returns'],['privacy.html','Privacy & device storage'],['terms.html','Using this website']].map(([p,t])=>`<a href="${u(p)}">${t}</a>`).join('')}</div></div><div class="cross-links">Also from Leighton: <a href="https://bytova.co.uk/">Bytova — technology &amp; small-business support</a> · <a href="https://retroreplay.uk/">RetroReplay UK — retro gaming</a></div><div class="footer-bottom"><span>© 2026 Stone & Sprig · A little room to grow.</span><span>Planned products · stock unconfirmed · checkout closed</span></div></div></footer>`;}
function shell(file,title,description,body,active=''){
 const prefix='../'.repeat(file.split('/').length-1)||'./',u=path=>prefix+path;
 const canonical=new URL(file==='index.html'?'':file,shop.baseUrl).href;
 const is404=file==='404.html';
 const html=`<!doctype html><html lang="en-GB"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">${is404?`<base href="${shop.baseUrl}"><meta name="robots" content="noindex">`:''}<title>${e(title)} | Stone & Sprig</title><meta name="description" content="${e(description)}"><meta name="theme-color" content="#284a37"><link rel="canonical" href="${canonical}"><meta property="og:site_name" content="Stone & Sprig"><meta property="og:type" content="website"><meta property="og:title" content="${e(title)}"><meta property="og:description" content="${e(description)}"><meta property="og:url" content="${canonical}"><meta property="og:image" content="${shop.baseUrl}assets/garden-inspiration.png"><meta name="twitter:card" content="summary_large_image">${verificationMeta()}<link rel="icon" href="${u('assets/stone-sprig-logo.png')}" type="image/png"><link rel="stylesheet" href="${u('styles.css')}?v=20261021-logo"><script src="${u('measurement.js')}" data-brand="garden" data-ga-id="G-SBLP603J4G" defer></script><script type="module" src="${u('app.mjs')}"></script></head><body><a class="skip" href="#main">Skip to content</a>${header(u,active)}<main id="main">${body(u,prefix)}</main>${footer(u)}<script src="https://stone-and-sprig.taccountant.chatgpt.site/assistant.js" defer></script><dialog class="basket-dialog" id="basket-dialog" aria-labelledby="basket-title"><div class="basket-panel"><div class="dialog-heading"><h2 id="basket-title">Your saved basket</h2><button type="button" class="icon-button" data-close-basket autofocus aria-label="Close basket">×</button></div><p class="small-note" style="margin-top:18px">Ideas for later. No stock is reserved and no payment is taken.</p><div data-basket-lines></div><div data-basket-summary></div><div class="button-row">${button(u,'checkout.html','Review saved basket')}${button(u,'shop.html','Keep exploring','outline')}</div></div></dialog><div class="toast" data-toast role="status" hidden></div><noscript><div class="noscript-note">All pages and product details can be read without JavaScript. Basket saving, filters, forms and planners need JavaScript enabled.</div></noscript></body></html>`;
 pages.set(file,{html,title,description});
}
function heading(u,label,title,intro){return `<div class="wrap"><div class="breadcrumb"><a href="${u('index.html')}">Home</a> / ${e(label)}</div><div class="page-heading"><span class="eyebrow">${label}</span><h1>${title}</h1><p class="lede">${intro}</p></div></div>`;}
function collectionCards(u){return collections.map((c,i)=>`<article class="collection-card"><span class="number">0${i+1}</span><span class="eyebrow">${e(c.label)}</span><h3>${e(c.name)}</h3><p>${e(c.description)}</p><a class="text-link" href="${u('collections/'+c.slug+'.html')}">Explore this collection →</a></article>`).join('');}
function journalCards(u,list=guides){return list.map((g,i)=>`<article class="journal-card"><span class="meta">${e(g.category)} · ${e(g.read)} read</span><span class="journal-icon" aria-hidden="true">${['i','ii','iii','iv','v'][i]}</span><h3><a href="${u('journal/'+g.slug+'.html')}">${e(g.title)}</a></h3><p>${e(g.intro)}</p><a class="text-link" href="${u('journal/'+g.slug+'.html')}">Read the note →</a></article>`).join('');}
function projectBanner(u){return `<div class="banner"><div><span class="eyebrow">A good place to begin</span><h2>A garden project on your mind?</h2><p>Tell us what you would like to change. We discuss the job, your area, timing and a written quote before any work is agreed.</p></div>${button(u,'project-brief.html','Build your project brief')}</div>`;}
const privacyCheck=u=>`<label class="check-label"><input type="checkbox" name="privacyAccepted" required><span>I have read the <a href="${u('privacy.html')}">privacy notice</a> and want Leighton to use these details to answer this enquiry. This does not subscribe me to marketing.</span></label>`;
const identityFields=`<div class="fields-2"><div class="field"><label for="visitor-name">Your name</label><input id="visitor-name" name="name" autocomplete="name" maxlength="50" required></div><div class="field"><label for="visitor-email">Email for a reply</label><input id="visitor-email" type="email" name="email" autocomplete="email" maxlength="254" required></div></div><div class="hp" aria-hidden="true"><label>Leave this field empty<input name="website" autocomplete="off" tabindex="-1"></label></div>`;

shell('index.html','A little room to grow','Garden ideas, individual project enquiries and an 18-product essentials range coming soon.',u=>`<section class="hero"><div class="hero-copy"><span class="eyebrow">Everyday gardens. Small beginnings.</span><h1>Make a little<br>room to <em>grow.</em></h1><p class="lede">A few pots. A corner worth keeping. A garden that feels more like you. Find practical ideas, plan your next small job or talk to us about a bigger change.</p><div class="button-row">${button(u,'garden-planner.html','Find your next garden job')}${button(u,'garden-projects.html','Discuss a project','outline')}</div><div class="hero-note">${sprig}<span>Our garden essentials shop is taking root. Browse 18 planned products and save ideas while stock and payments are being prepared.</span></div></div><figure class="hero-picture"><img src="${u('assets/garden-inspiration.png')}" width="1536" height="1024" alt="A garden inspiration scene with a curved gravel path, autumn planting and a potting bench" fetchpriority="high"><figcaption class="image-caption">AI-generated garden inspiration · not a completed customer project</figcaption></figure></section><div class="wrap route-strip"><a class="route-item" href="${u('shop.html')}">${basketIcon}<div><strong>Browse the planned shop</strong><span>Useful essentials · coming soon</span></div></a><a class="route-item" href="${u('garden-projects.html')}">${sprig}<div><strong>A project, talked through</strong><span>Start with your goal and your space</span></div></a><a class="route-item" href="${u('community.html')}">${sprig}<div><strong>Meet at the Potting Bench</strong><span>Small challenges &amp; shared curiosity</span></div></a></div><section class="section"><div class="wrap">${sectionHead('Useful, by the handful','Little essentials.<br>Thoughtful choices.','Start with the job you want to do. Our planned range brings together simple tools, potting extras and plant supports.')}<div class="status-note" style="margin-bottom:28px">${coming} Product pictures are illustrations; final models and specifications may change.</div><div class="product-grid">${productGrid(products.filter(p=>[1,8,9,16].includes(p.id)))}</div><div class="button-row" style="margin-top:30px">${button(u,'shop.html','Explore all 18 planned products','outline')}</div></div></section><section class="section sand"><div class="wrap">${sectionHead('Start with a small job','A few things that<br>work well together.')}<div class="grid-3">${collectionCards(u)}</div></div></section><section class="section"><div class="wrap split"><div class="botanical-panel">${botanical}<span class="panel-label">A little room to grow</span></div><div><span class="eyebrow">Garden projects, with a human beginning</span><h2>You bring the idea.<br>We talk it through.</h2><p class="muted">You do not need a perfect plan to begin. Describe what would make your garden easier to use or more enjoyable, and we can discuss whether we can help.</p><ol class="step-list"><li><strong>Tell us about your space</strong>Build a brief with your goal, approximate size and town or postcode district.</li><li><strong>Agree what is possible</strong>Scope, service coverage, access, timing and price are checked for your individual project.</li><li><strong>Choose your next step</strong>No visit or work is booked until the details and a written quote are agreed.</li></ol>${button(u,'project-brief.html','Start a project brief')}</div></div></section><section class="section sage"><div class="wrap">${sectionHead('The garden journal','Good notes for<br>the growing season.')}<div class="grid-3">${journalCards(u,guides.slice(0,3))}</div><a class="text-link" href="${u('journal.html')}">Browse all garden notes →</a></div></section><section class="section"><div class="wrap">${projectBanner(u)}</div></section>`);

shell('shop.html','The planned garden shop','Explore all 18 planned garden products. Search, filter and save a basket; stock and payments are not open.',(u,root)=>`${heading(u,'The planned shop','Useful things for<br>everyday gardening.','Explore the essentials, check what suits your job and save a basket for later. All 18 products are coming soon.')}<section class="section compact"><div class="wrap"><div class="status-note">${coming} Prices are planned, delivery is proposed, and illustrations do not show a confirmed supplied model.</div><form class="toolbar" data-shop-filters role="search"><div class="field"><label for="product-search">Find a garden essential</label><input id="product-search" name="query" type="search" maxlength="100" placeholder="Try pots, gloves or plant ties"></div><div class="field"><label for="product-category">Browse by job or category</label><select id="product-category" name="category"><option value="all">All garden essentials</option><optgroup label="By job"><option value="tidy">Tidy a little</option><option value="grow">Pot &amp; plant</option><option value="support">Support plants</option></optgroup><optgroup label="By category">${[...new Set(products.map(p=>p.category))].map(c=>`<option value="${e(c)}">${e(c)}</option>`).join('')}</optgroup></select></div><div class="field"><label for="product-sort">Show me</label><select id="product-sort" name="sort"><option value="featured">Featured order</option><option value="price-asc">Price: low to high</option><option value="price-desc">Price: high to low</option><option value="name">Name: A to Z</option></select></div></form><p class="results-count" data-results-count role="status">18 planned products · all coming soon</p><div class="product-grid" data-product-grid>${productGrid(products,root)}</div><div style="margin-top:55px">${projectBanner(u)}</div></div></section>`,'shop');
for(const p of products)shell(`products/${p.slug}.html`,p.name,p.description,(u,root)=>`<div class="wrap"><div class="breadcrumb"><a href="${u('index.html')}">Home</a> / <a href="${u('shop.html')}">Shop</a> / ${e(p.name)}</div></div><section class="section compact"><div class="wrap product-detail"><div><div class="product-image">${productArt(p.art)}<span class="coming-tag">Coming soon · illustration</span></div><p class="small-note" style="margin-top:12px">Original product illustration. Colour, shape and final supplied model are not confirmed.</p></div><div><span class="eyebrow">${e(p.category)}</span><h1>${e(p.name)}</h1><p class="lede">${e(p.description)}</p><p class="detail-price">${money(p.price)} <small class="small-note">planned price</small></p><p class="small-note">Stock unconfirmed · online payment closed</p><div class="button-row"><button class="button" type="button" data-add="${p.slug}">Save to basket</button>${button(u,'contact.html?topic=products&product='+p.slug,'Ask about this product','outline')}</div><div class="detail-points"><h2 class="detail-subtitle">A little more detail</h2><p>${e(p.detail)}</p><h2 class="detail-subtitle">Before you choose</h2><p>${e(p.check)}</p></div><div class="status-note">${coming} Saving this item is a personal shortlist, not an order or stock reservation. <a href="${u('delivery.html')}">Shop and delivery status</a>.</div></div></div></section><section class="section sand"><div class="wrap">${sectionHead('A few related ideas','For the same little job.')}<div class="product-grid">${productGrid(p.related.map(id=>products.find(x=>x.id===id)),root)}</div></div></section>`,'shop');
shell('collections.html','Garden collections','Explore three thoughtful selections for tidying, potting and supporting plants.',u=>`${heading(u,'Garden collections','Start with the job.<br>Keep it simple.','Three small selections from our coming-soon range. Choose only what you need; these are ideas, not discounted bundles.')}<section class="section compact"><div class="wrap"><div class="grid-3">${collectionCards(u)}</div><div style="margin-top:40px">${projectBanner(u)}</div></div></section>`,'shop');
for(const c of collections){const chosen=c.ids.map(id=>products.find(p=>p.id===id));shell(`collections/${c.slug}.html`,c.name,c.description,(u,root)=>`${heading(u,'Garden collection',e(c.name),e(c.description))}<section class="section compact"><div class="wrap"><div class="status-note"><strong>Planned selection: ${money(chosen.reduce((n,p)=>n+p.price,0))}</strong> for one of each of the ${chosen.length} products below, before proposed delivery. There is no bundle discount. All items are coming soon and specifications are unconfirmed.</div><div class="product-grid" style="margin-top:30px">${productGrid(chosen,root)}</div><div class="button-row" style="margin-top:30px"><button class="button" type="button" data-add-collection="${c.slug}">Save these ${chosen.length} ideas</button>${button(u,`journal/${c.guide}.html`,'Read the related garden note','outline')}</div></div></section>`,'shop');}

shell('garden-projects.html','Garden projects, talked through','Describe your garden goal. Scope, area, access, availability and a written quote are discussed individually.',u=>`${heading(u,'Garden projects','A better garden<br>starts with a conversation.','A small change can make a space easier to use, easier to care for or simply more enjoyable. Tell us the result you have in mind.')}<section class="section compact"><div class="wrap split"><div><span class="eyebrow">Your garden. Your priorities.</span><h2>Bring the problem.<br>We can shape the brief.</h2><p class="muted">Perhaps a corner needs a reset, you want to rethink some planting or you are unsure where to begin. These are starting points for discussion. Each job is assessed individually.</p><ul class="plain-list"><li>A small tidy or seasonal reset</li><li>Planting, pots or a border idea</li><li>Making your space easier to look after</li><li>A different garden project you would like to discuss</li></ul><div class="status-note">Service coverage, suitability, availability and price are not yet confirmed for your location. Sending a brief is an enquiry. It does not book a visit or agree any work.</div><div class="button-row" style="margin-top:25px">${button(u,'project-brief.html','Build your project brief')}${button(u,'contact.html?topic=project','Ask a quick question','outline')}</div></div><div class="botanical-panel">${botanical}<span class="panel-label">Begin with the space you have</span></div></div></section><section class="section sand"><div class="wrap">${sectionHead('From idea to agreement','No perfect plan required.')}<div class="grid-3"><article class="collection-card"><span class="number">01</span><h3>Tell us the goal</h3><p>What would you like to change? Include approximate size, your town or postcode district, access and anything you want to keep.</p></article><article class="collection-card"><span class="number">02</span><h3>Check the practicalities</h3><p>We discuss the job and confirm whether the scope and location are suitable. A conversation or a visit may be needed before pricing.</p></article><article class="collection-card"><span class="number">03</span><h3>Agree it in writing</h3><p>Any visit, work, price, timing and payment arrangements must be agreed first. No service purchase is taken through this website.</p></article></div></div></section><section class="section"><div class="wrap">${projectBanner(u)}</div></section>`,'projects');
shell('project-brief.html','Build a garden project brief','Prepare a useful project brief. Copy it, download it or send it privately to Leighton.',u=>`${heading(u,'Your project brief','Tell us what you<br>would love to change.','Build a brief without signing up. You can keep it for yourself, or choose to send it privately to Leighton for discussion.')}<section class="section compact"><div class="wrap form-layout"><form class="form-card" data-brief><h2>Begin with your garden</h2><div class="field"><label for="project-type">What would you like to discuss?</label><select id="project-type" name="project"><option>A small tidy or seasonal reset</option><option>Planting, pots or a border idea</option><option>Making the space easier to care for</option><option>A different garden project</option><option>Help working out where to begin</option></select></div><div class="field"><label for="project-goal">What would a good result look like?</label><textarea id="project-goal" name="goal" minlength="10" maxlength="1000" rows="4" required placeholder="Tell us what is difficult now and what you would like to change."></textarea></div><div class="fields-2"><div class="field"><label for="project-size">Approximate size (optional)</label><input id="project-size" name="size" maxlength="120" placeholder="For example, a 3m × 2m border"></div><div class="field"><label for="project-area">Town or postcode district (optional)</label><input id="project-area" name="area" maxlength="80" placeholder="Town or first part of postcode"></div><div class="field"><label for="project-timing">When are you thinking?</label><select id="project-timing" name="timing"><option>Flexible / to discuss</option><option>Within the next month, if available</option><option>Over the next few months</option><option>Planning ahead for next season</option></select></div><div class="field"><label for="project-budget">Indicative budget (optional)</label><select id="project-budget" name="budget"><option>To discuss</option><option>Under £250</option><option>£250–£500</option><option>£500–£1,000</option><option>£1,000–£2,500</option><option>Over £2,500</option></select></div></div><div class="field"><label for="project-access">Access and things to keep (optional)</label><textarea id="project-access" name="access" maxlength="700" rows="3" placeholder="Steps, narrow access, favourite plants or other practical details. Please leave out sensitive information."></textarea></div><button class="button" type="submit">Prepare my brief</button><p class="feedback" data-brief-feedback role="status"></p><p class="small-note">Nothing is sent when you prepare a brief. Do not include a full address, payment details or private information about other people.</p></form><div><section class="result-card" aria-labelledby="brief-title"><span class="eyebrow">A useful starting point</span><h2 id="brief-title" tabindex="-1">Your project, in a few words.</h2><label for="brief-output">Your prepared brief</label><textarea class="brief-output" id="brief-output" data-brief-output readonly placeholder="Your brief will appear here when you select Prepare my brief."></textarea><div class="button-row" style="margin-top:18px"><button class="button small" data-copy-brief type="button" disabled>Copy brief</button><button class="button small outline" data-download-brief type="button" disabled>Download brief</button></div><p class="feedback" data-copy-feedback role="status"></p><p class="small-note">No work or visit is booked. Scope, service coverage, access, availability and a written quote must be agreed first.</p></section><form class="form-card" style="margin-top:24px" data-send-brief><h2>Want to discuss it?</h2><p class="small-note">After preparing your brief, add a name and email to send it privately. No newsletter subscription or automatic booking is created.</p>${identityFields}${privacyCheck(u)}<button class="button" type="submit" data-send disabled>Send my brief privately</button><p class="feedback" data-send-feedback role="status"></p></form></div></div></section>`,'projects');

shell('garden-planner.html','Your next little garden job','Build a seasonal garden checklist for your space, goal and time. No account or email needed.',u=>`${heading(u,'A little garden planner','Small plans.<br>A satisfying start.','Pick your space, a goal and the time you have. Leave with a short checklist, with no account or email required.')}<section class="section compact"><div class="wrap form-layout"><form class="form-card" data-planner><h2>What have you got in mind?</h2><div class="fields-2"><div class="field"><label for="plan-season">Season</label><select id="plan-season" name="season"><option value="autumn">Autumn</option><option value="winter">Winter</option><option value="spring">Spring</option><option value="summer">Summer</option></select></div><div class="field"><label for="plan-space">Your growing space</label><select id="plan-space" name="space"><option value="small">A small garden</option><option value="pots">Pots, patio or balcony</option><option value="family">A family garden</option><option value="allotment">An allotment or growing bed</option></select></div><div class="field"><label for="plan-goal">A good job for today</label><select id="plan-goal" name="goal"><option value="tidy">Tidy a little</option><option value="grow">Plan some planting</option><option value="support">Check plant supports</option><option value="wildlife">Make room for wildlife</option></select></div><div class="field"><label for="plan-time">Time to spend</label><select id="plan-time" name="time"><option value="20">About 20 minutes</option><option value="60">About an hour</option><option value="half-day">A relaxed half-day</option></select></div></div><button class="button" type="submit">Make my little garden plan</button><p class="small-note" style="margin-top:20px">These are general ideas for UK gardens. Conditions and plant needs vary. Check the weather, your tools and plant-specific guidance before starting.</p><a class="text-link" href="https://www.rhs.org.uk/advice/in-month">RHS month-by-month advice →</a></form><section class="result-card" data-plan-result aria-labelledby="plan-title"><span class="eyebrow">Your next little job</span><h2 id="plan-title" tabindex="-1">A plan you can actually start.</h2><p>Choose your space and select “Make my little garden plan” to begin.</p></section></div></section><section class="section sand" data-plan-products-section hidden><div class="wrap">${sectionHead('Optional ideas for later','Only if you need them.','Use what you have. These matching products are from the planned range and are all coming soon.')}<div class="product-grid" data-plan-products></div></div></section>`,'planner');

shell('journal.html','The garden journal','Practical, seasonal garden notes for small spaces, wildlife, plant care and planning a project.',u=>`${heading(u,'The garden journal','Good notes.<br>Better small beginnings.','Practical reading for the patch, pot or project in front of you. Start small, work with the conditions and leave a little room for nature.')}<section class="section compact"><div class="wrap grid-3">${journalCards(u)}</div></section>`,'journal');
for(const g of guides)shell(`journal/${g.slug}.html`,g.title,g.intro,(u,root)=>`${heading(u,g.category,e(g.title),e(g.intro))}<section class="section compact"><div class="wrap article-layout"><article class="content-article"><p class="small-note">Stone & Sprig journal · ${e(g.read)} read · Updated 20 October 2026</p>${g.sections.map(([title,text])=>`<h2>${e(title)}</h2><p>${e(text)}</p>`).join('')}${g.source.length?`<div class="source-list"><strong>Further reading</strong><p>General garden guidance can depend on the plant and local conditions. These RHS resources offer more detail.</p>${g.source.map(([label,url])=>`<a href="${e(url)}">${e(label)} →</a>`).join('')}</div>`:''}<div class="button-row" style="margin-top:35px">${button(u,'garden-planner.html','Make a small garden plan')}${button(u,'journal.html','More garden notes','outline')}</div></article><aside class="aside-card"><span class="eyebrow">From reading to doing</span><h2>A little job for your space.</h2><p>Turn an idea into a short, seasonal checklist, or build a brief for something bigger.</p>${button(u,'garden-planner.html','Try the garden planner','small')}<p style="margin:20px 0 0"><a class="text-link" href="${u('project-brief.html')}">Discuss a project →</a></p></aside></div></section>${g.products.length?`<section class="section sand"><div class="wrap">${sectionHead('If it suits the job','Ideas from the planned shop.','These are optional product ideas, not a required shopping list. All are coming soon.')}<div class="product-grid">${productGrid(g.products.map(id=>products.find(p=>p.id===id)),root)}</div></div></section>`:''}`,'journal');

shell('community.html','The Potting Bench','A friendly place to begin: small garden challenges, reflective prompts and practical reading.',u=>`${heading(u,'The Potting Bench','Every garden<br>has a beginning.','A place for small experiments and the pleasure of noticing what grows. Try a gentle garden challenge, keep a note and make the space your own.')}<section class="section compact"><div class="wrap community-grid"><div><span class="eyebrow">This week’s little challenge</span><h2>Find your favourite<br>ten-minute corner.</h2><p class="muted">Step outside, choose one corner and spend ten minutes noticing it. Where does the light fall? What is growing without much help? What would make the spot easier to enjoy?</p><ul class="checklist"><li><label><input type="checkbox"><span>Notice one thing worth keeping.</span></label></li><li><label><input type="checkbox"><span>Choose one small change, if it needs one.</span></label></li><li><label><input type="checkbox"><span>Take a private note or photo to compare next month.</span></label></li></ul><p class="small-note">These challenge ticks last while this page is open. There is no public post or upload.</p>${button(u,'garden-planner.html','Make a plan for that corner','outline')}</div><div class="prompt-card"><span class="eyebrow">A thought from the potting bench</span><blockquote data-garden-prompt>What is one thing your garden does well, just as it is?</blockquote><button class="button small" type="button" data-next-prompt>Give me another thought</button><p class="small-note" style="margin-top:20px">A handful of original conversation starters. Nothing you type or think here is collected.</p></div></div></section><section class="section sage"><div class="wrap">${sectionHead('For the curious gardener','A little reading to grow with.')}<div class="grid-3">${journalCards(u,guides.filter(g=>['small-space-gardening','wildlife-friendly-corner','plant-support'].includes(g.slug)))}</div></div></section><section class="section"><div class="wrap banner"><div><span class="eyebrow">Help shape the Potting Bench</span><h2>What would you like to learn?</h2><p>Send a garden question or an idea for a future guide. Messages are private. A public discussion board and member accounts are not currently available.</p></div>${button(u,'contact.html?topic=community','Send a garden question')}</div></section>`,'community');
shell('about.html','Our approach','Small beginnings, practical garden ideas and individual project conversations with Leighton.',u=>`${heading(u,'Our approach','Good gardens.<br>Everyday beginnings.','Stone & Sprig is being built around a simple idea: a garden should be a space you can enjoy, with manageable steps towards making it your own.')}<section class="section compact"><div class="wrap split"><article class="content-article"><h2>A note from Leighton</h2><p>I am building Stone & Sprig as a home for practical garden ideas, useful essentials and conversations about individual garden projects.</p><p>You can browse the planned shop, use the free planner and prepare a project brief today. The shop is still being prepared: stock, final product details and online payments must be confirmed before orders open.</p><h2>Useful before impressive</h2><p>We begin with what you need, what is already working and the time you actually have. A small, well-chosen job can be a good place to start.</p><h2>Room for nature</h2><p>A garden does not have to be spotless to be cared for. Our journal encourages thoughtful planting, sensible maintenance and space for wildlife.</p><h2>Clear conversations</h2><p>Every project is discussed first. We check scope, location, practical access, timing and price before any work is agreed.</p>${button(u,'contact.html','Talk to Leighton')}</article><div class="botanical-panel">${botanical}<span class="panel-label">A little room to grow</span></div></div></section>`);
shell('contact.html','Contact Leighton','Send a private garden enquiry, product question or idea for the Potting Bench.',u=>`${heading(u,'Contact','Let’s talk<br>about your garden.','Ask a question about a project, the planned shop or a future garden note. Your enquiry goes privately to Leighton.')}<section class="section compact"><div class="wrap form-layout"><form class="form-card" data-contact><h2>Send a private enquiry</h2>${identityFields}<div class="field"><label for="contact-topic">What is it about?</label><select id="contact-topic" name="route"><option value="general">A general garden enquiry</option><option value="project">A garden project</option><option value="products">The planned product range</option><option value="community">A Potting Bench question or idea</option><option value="privacy">A privacy question</option></select></div><div class="field"><label for="contact-title">Subject</label><input id="contact-title" name="title" minlength="3" maxlength="120" required></div><div class="field"><label for="contact-body">Your message</label><textarea id="contact-body" name="body" minlength="20" maxlength="3000" rows="6" required placeholder="Tell us a little about what you need (at least 20 characters). Please leave out sensitive details and payment information."></textarea></div>${privacyCheck(u)}<button class="button" type="submit" data-send>Send my enquiry</button><p class="feedback" data-send-feedback role="status"></p><p class="small-note">Submitting does not book work, order a product or join a mailing list. A saved reference confirms receipt; an email acknowledgement is not sent automatically.</p></form><aside class="result-card"><span class="eyebrow">A real conversation</span><h2>A useful next step,<br>with no pressure.</h2><p>For a project, your town or postcode district, approximate size and what you would like to change help us begin.</p>${button(u,'project-brief.html','Build a project brief','outline')}<h3 style="margin-top:35px">Before you send</h3><p class="small-note">Garden phone, public email and service coverage details are still being finalised. This form is the current way to contact Leighton about Stone & Sprig.</p><p class="small-note">Enquiries are handled in the shared private owner inbox used by Leighton’s websites, hosted at RetroReplay UK. Your message stays private. Reply timing and project availability are not guaranteed.</p><a class="text-link" href="${u('privacy.html')}">How your details are used →</a></aside></div></section>`);

const faqs=[['Can I buy the products yet?','Not yet. All 18 products are coming soon. You can read their details and save a basket, but stock has not been confirmed and online payment is closed.'],['What does “save to basket” mean?','It saves product IDs and quantities on this device for your own planning. It does not order, reserve or promise availability. You can change quantities or clear the basket at any time.'],['Are these the final prices and product photos?','Prices are planned and may change before the shop opens. The product pictures are original illustrations, not supplier photographs. Final models, materials, dimensions and pack details must be checked before sale.'],['Where do you deliver?','Delivery coverage, carriers and dispatch times are not confirmed. The basket currently illustrates a proposed £3.99 delivery charge, free from £50. Those are planning figures, not a delivery offer.'],['Which garden services can I book?','Start by describing your goal. Every project is discussed individually and scope, location, suitability, access, availability and a written quote must be agreed. Sending a message does not book a visit or work.'],['Can I use the planner without giving my email?','Yes. The planner runs on this device. You can use, copy, print and optionally save a plan without providing contact details.'],['Is the Potting Bench a public forum?','It currently offers challenges, garden prompts and guides. You can send a private question or suggest a topic. Public posts, member accounts and an automatic newsletter are not available.'],['How do I contact you?','Use the private contact form, or prepare and send a project brief. Garden phone and public email details are still being finalised. No automatic email acknowledgement is promised.']];
shell('help.html','Questions and answers','Straightforward answers about the planned shop, saved baskets, garden projects and free planner.',u=>`${heading(u,'A little help','Good questions.<br>Clear answers.','Here is how the site works today, and what is still being prepared.')}<section class="section compact"><div class="wrap narrow"><div class="faq">${faqs.map(([q,a])=>`<details><summary>${e(q)}</summary><p>${e(a)}</p></details>`).join('')}</div><div class="button-row" style="margin:30px 0">${button(u,'contact.html','Ask a different question')}${button(u,'shop.html','Explore the planned shop','outline')}</div></div></section>`);
shell('delivery.html','Shop and delivery status','A clear explanation of the coming-soon shop, unconfirmed stock and proposed delivery figures.',u=>`${heading(u,'Shop & delivery status','The shop is<br>taking root.','You can explore and plan today. Orders, payment and delivery are not yet open.')}<section class="section compact"><article class="wrap content-article"><div class="status-note">${coming}</div><h2>What you can do now</h2><p>Browse all 18 products, read the provisional details and save items in a basket on this device. You can ask a private product question. None of these actions creates an order or reservation.</p><h2>What is still being checked</h2><p>Supplier availability, stock purchase, delivered costs, final models and specifications, sale prices, service and delivery coverage, dispatch arrangements, seller contact details and live payment setup must be confirmed before sales begin.</p><h2>Proposed delivery figures</h2><p>Basket calculations currently show £3.99 delivery below a £50 items subtotal and free delivery from £50. These are planning figures only. No delivery area, carrier, dispatch date or delivery time is promised.</p><h2>Before you will be asked to pay</h2><p>The shop must show the actual offered product, its confirmed price and availability, full seller and contact information, delivery arrangements, applicable sales terms and a working secure payment flow. A saved basket must be checked against those details when sales open.</p><div class="button-row">${button(u,'shop.html','Explore the planned range')}${button(u,'contact.html?topic=products','Ask a product question','outline')}</div></article></section>`);
shell('returns.html','Orders and returns','No Outdoor Living Co. orders are currently accepted; how to ask an order or return question.',u=>`${heading(u,'Orders & returns','Questions before<br>the shop opens.','Stone & Sprig is not currently taking online orders or payments.')}<section class="section compact"><article class="wrap content-article"><h2>No order is created by saving a basket</h2><p>A saved basket is a personal planning list on this device. It has no order number, payment or reserved stock, and there is nothing to cancel or return through that list.</p><h2>Sales policies are being prepared</h2><p>Confirmed seller details, delivery arrangements and the applicable order, cancellation, return and faulty-goods information will be available before products can be purchased. No paid return service or shortened return period is being offered here.</p><h2>Already have a question?</h2><p>If you believe you have paid or agreed work elsewhere, contact Leighton with the reference and where that agreement was made. Do not include card numbers, passwords or bank details. We can review the circumstances; this page does not change any rights or agreement you already have.</p>${button(u,'contact.html','Ask about an order or agreement')}</article></section>`);
shell('terms.html','Using this website','How to use the garden information, planner, saved basket and private enquiry forms.',u=>`${heading(u,'Using this website','A clear starting point.','This website is operated by Leighton Hepworth for Stone & Sprig. Updated 20 October 2026.')}<section class="section compact"><article class="wrap content-article"><h2>Garden ideas and planning tools</h2><p>The journal and planner provide general garden information. They cannot assess your particular site, plant, weather, tools or project. Use suitable instructions and plant-specific guidance, and ask for appropriate professional advice where a job needs it.</p><h2>The planned shop</h2><p>Catalogue products, prices, pictures and delivery calculations are provisional. All items are coming soon, stock is unconfirmed and checkout is closed. Saving a basket is not an order, reservation or contract. Confirmed sales information and terms must be published before orders open.</p><h2>Project enquiries</h2><p>Submitting a brief or question asks us to discuss it. It does not confirm coverage, availability, a visit or work. Scope, practical details, price, timing and any payment arrangements must be agreed in writing before proceeding.</p><h2>Your messages</h2><p>Share only information you have the right to provide. Keep passwords, payment details, sensitive personal information and private details about others out of enquiries. Messages are private and do not become public community posts.</p><h2>Pictures and garden notes</h2><p>The home-page garden picture is AI-generated inspiration, not a completed customer project. Product artwork is illustrative and does not show a confirmed supplied model. External resources have their own content and terms.</p><h2>Questions</h2><p>Use the contact form to ask Leighton about the site, a project or a planned product. Garden phone, public email, sales details and service coverage remain to be confirmed.</p>${button(u,'contact.html','Contact Leighton','outline')}</article></section>`);
shell('privacy.html','Privacy and device storage','What the garden site stores on your device and how private enquiries are handled.',u=>`${heading(u,'Privacy & device storage','Your garden ideas.<br>Your choice to share.','This notice explains the current website and its private enquiry forms. Website operator: Leighton Hepworth. Updated 22 October 2026.')}<section class="section compact"><article class="wrap content-article"><h2>Browsing, baskets and plans</h2><p>You can read the site and use the garden planner without providing your name or email. The basket stores only known product IDs and quantities in local storage named gardenCart. An optional saved planner uses garden-plan-v1 to store your selected season, space, goal, time and checked tasks. These stay in the browser on this device; we do not receive a copy just because you save them.</p><p>Use the clear controls or your browser settings to remove these lists. If browser storage is unavailable, the current page can still work, but your list may not survive navigation. Project brief text remains in the open page until you choose to copy, download or send it. Downloaded files and clipboard contents are under your control.</p><h2>When you choose to send an enquiry</h2><p>The form collects the name, reply email, topic, subject and message you provide. A project brief can also include your chosen project type, goal, approximate size, town or postcode district, timing, indicative budget and access notes. Only include details you want Leighton to review.</p><p>We use the information to respond and take the steps you request before a possible agreement, and for our legitimate interests in handling questions and preventing misuse. A short campaign label in the page link may be included with your enquiry to identify the route you used. It does not collect browsing history. The privacy checkbox confirms you have read this notice and want a reply; it does not subscribe you to marketing.</p><h2>Conversation assistant</h2><p>Sprig uses the published garden information to guide a project or planning conversation. Once you interact, recent chat and choices stay in session storage on this website in this tab for up to six hours. Close the tab or choose Forget this chat to clear it. It is not sent to an external AI provider or saved as an enquiry by chatting alone. You can copy your brief and submit it separately through the private form. Movement can be paused and respects reduced-motion preferences.</p><h2>A dedicated Stone &amp; Sprig customer area</h2><p>ChatGPT sign-in links your account to your own requests, quotes, agreed visits, messages and files. Private owner notes stay hidden from customer accounts. See <a href="https://stone-and-sprig.taccountant.chatgpt.site/portal/privacy">customer area privacy information</a>.</p><h2>A dedicated private owner inbox</h2><p>Enquiries are sent securely to the dedicated Stone &amp; Sprig enquiry service at https://stone-and-sprig.taccountant.chatgpt.site. They are labelled Stone & Sprig and remain in the protected owner area. They cannot be published as community stories. The owner can record a reply stage, next action, follow-up date and private notes for your request.</p><p>GitHub Pages hosts this public website. OpenAI Sites and Cloudflare operate the private enquiry service. No automatic email alert, customer acknowledgement or marketing subscription is created by the new dedicated enquiry service. Leighton reviews enquiries in the private owner dashboard. Hosting and security providers process technical connection details and logs to operate and protect their services.</p><h2>How long information is kept</h2><p>Private enquiries are kept while active and normally removed twelve months after closure during maintenance. Information needed for an agreement, accounting, a dispute or a legal obligation may need a different retention period. The current garden site takes no payment and collects no card or delivery-address details.</p><h2>Optional website statistics</h2><p>Statistics are off unless you choose Allow statistics. Privacy choices lets you change that at any time. We store that choice on this device as business-statistics-choice-v1 for up to 180 days. With permission, the shared private service at retroreplay.uk counts public page paths, selected actions and known campaign labels in daily aggregates for up to 90 days. It does not store names, emails, form contents, order tokens, IP addresses, visitor IDs or browsing histories in the statistics. A separate hashed connection key is used briefly to limit abuse. Counts describe consented events, not unique people or all traffic. The Google tag is present in consent-denied mode so installation can be detected, but analytics storage stays denied and we do not send our analytics events until you choose Allow statistics. If you allow statistics, Google Analytics 4 measures consented page views and selected actions. Google signals and advertising-personalisation signals are disabled. Form text, names, email addresses and private enquiry contents are not sent as analytics events. Essential contact and shopping features work when statistics are off.</p><h2>Your choices</h2><p>You may ask for access, correction or erasure of your information, and for restriction, portability or to object where the relevant right applies. Choose “A privacy question” on the contact form and include an enquiry reference if you have one. We may need to verify your identity. We normally respond within one month, and explain any lawful extension. You can also complain to the Information Commissioner’s Office.</p><p>We have not added advertising trackers, public uploads or a newsletter subscription. Optional analytics events and analytics storage are enabled only after the separate choice described above. No solely automated decision with a legal or similarly significant effect is made about you by this site. Providers may process information outside the UK; applicable transfer safeguards depend on the provider and service.</p><div class="source-list"><strong>Provider and privacy information</strong><a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement">GitHub privacy statement →</a><a href="https://openai.com/policies/privacy-policy/">OpenAI privacy policy →</a><a href="https://www.cloudflare.com/privacypolicy/">Cloudflare privacy policy →</a><a href="https://resend.com/legal/privacy-policy">Resend privacy policy →</a><a href="https://ico.org.uk/for-the-public/">ICO: your data protection rights →</a></div><div class="button-row" style="margin-top:25px">${button(u,'contact.html?topic=privacy','Ask a privacy question','outline')}</div></article></section>`);
shell('checkout.html','Review your saved basket','Review planned garden products. Online ordering and payment are closed; saving does not reserve stock.',u=>`${heading(u,'Saved basket','Good ideas,<br>ready for later.','Review your planned items and quantities. This is a shortlist, with no order, payment or stock reservation.')}<section class="section compact"><div class="wrap checkout-layout"><div><div data-review-lines><p>Your saved items will appear here with JavaScript enabled.</p></div><div class="button-row" style="margin-top:22px">${button(u,'shop.html','Keep exploring','outline')}<button class="button outline" data-clear-basket type="button">Clear saved basket</button></div></div><aside class="checkout-panel"><h2>A planning total</h2><div data-review-summary></div><div class="status-note"><strong>Checkout is closed.</strong> Stock and payments have not been confirmed. No address or card details are collected here.</div><p class="small-note" style="margin-top:20px">Final availability, product details, prices, delivery and seller information must be checked before a purchase becomes possible.</p>${button(u,'contact.html?topic=products','Ask about the planned range')}<p style="margin-top:18px"><a class="text-link" href="${u('delivery.html')}">Read the shop status →</a></p></aside></div></section>`,'shop');
shell('404.html','Find your way back to the garden','This garden page could not be found. Explore the planned shop, garden planner or contact page.',u=>`${heading(u,'Page not found','A little off<br>the garden path.','This page could not be found. These are good places to begin again.')}<section class="section compact"><div class="wrap button-row">${button(u,'index.html','Back to the garden')}${button(u,'shop.html','Explore the planned shop','outline')}${button(u,'contact.html','Ask for help','outline')}</div></section>`);
await mkdir(resolve(project,'assets'),{recursive:true});
await writeFile(resolve(project,'assets/sprig.svg'),sprig.replace('aria-hidden="true"','xmlns="http://www.w3.org/2000/svg"').replaceAll('currentColor','#284a37'));
for(const[file,{html}]of pages){await mkdir(dirname(resolve(project,file)),{recursive:true});await writeFile(resolve(project,file),html+'\n');}
await writeFile(resolve(project,'sitemap.xml'),'<?xml version="1.0" encoding="UTF-8"?>\n<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+[...pages].filter(([file])=>!['checkout.html','404.html'].includes(file)).map(([file])=>`<url><loc>${new URL(file==='index.html'?'':file,shop.baseUrl).href}</loc><lastmod>2026-10-20</lastmod></url>`).join('')+'</urlset>\n');
await writeFile(resolve(project,'robots.txt'),`User-agent: *\nAllow: /\nSitemap: ${shop.baseUrl}sitemap.xml\n`);
await writeFile(resolve(project,'.nojekyll'),'');
console.log(`Built ${pages.size} Outdoor Living Co. pages and ${products.length} planned product details.`);
